// Shared loader for rust/reference/params.json (generated by tools/export_reference.py).
#![allow(dead_code)]

use serde::Deserialize;

#[derive(Deserialize)]
pub struct Spec {
    pub name: String,
    pub default: f64,
    pub lo: f64,
    pub hi: f64,
    pub curve: String,
    pub unit: String,
    pub smooth_ms: f64,
    pub clamp_in: Vec<f64>,
    pub clamp_out: Vec<f64>,
    #[serde(default)]
    pub to_norm_out: Vec<f64>,
    #[serde(default)]
    pub from_norm_in: Vec<f64>,
    #[serde(default)]
    pub from_norm_out: Vec<f64>,
}

#[derive(Deserialize)]
pub struct SmootherCase {
    pub start: f64,
    pub target: f64,
    pub sample_rate: f64,
    pub time_ms: f64,
    pub steps: Vec<i64>,
    pub values: Vec<f64>,
}

#[derive(Deserialize)]
pub struct Reference {
    pub version: u32,
    pub synth: Vec<Spec>,
    pub drums: Vec<Spec>,
    pub smoother: Vec<SmootherCase>,
}

pub fn load() -> Reference {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../reference/params.json");
    let text = std::fs::read_to_string(path).expect("reference file");
    let r: Reference = serde_json::from_str(&text).expect("valid reference");
    assert_eq!(r.version, 1);
    r
}

pub fn close(a: f64, b: f64) -> bool {
    a == b || (a - b).abs() <= 1e-12 * a.abs().max(b.abs())
}

fn reference_path(file: &str) -> String {
    format!("{}/../reference/{file}", env!("CARGO_MANIFEST_DIR"))
}

/// Binary reference written by `tools/refio.py`: `<name>.f64` + `<name>.json`.
pub struct Blob {
    data: Vec<f64>,
    entries: serde_json::Map<String, serde_json::Value>,
}

impl Blob {
    pub fn open(name: &str) -> Blob {
        let raw = std::fs::read(reference_path(&format!("{name}.f64"))).expect("blob .f64");
        let data = raw
            .as_chunks::<8>()
            .0
            .iter()
            .map(|c| f64::from_le_bytes(*c))
            .collect();
        let text =
            std::fs::read_to_string(reference_path(&format!("{name}.json"))).expect("blob .json");
        let mut json: serde_json::Value = serde_json::from_str(&text).expect("valid blob json");
        let entries = json["entries"].as_object_mut().expect("entries").clone();
        Blob { data, entries }
    }

    fn entry(&self, label: &str) -> &serde_json::Value {
        self.entries
            .get(label)
            .unwrap_or_else(|| panic!("no entry {label:?}"))
    }

    pub fn get(&self, label: &str) -> &[f64] {
        let e = self.entry(label);
        let off = e["offset"].as_u64().unwrap() as usize;
        let len = e["len"].as_u64().unwrap() as usize;
        &self.data[off..off + len]
    }

    pub fn meta(&self, label: &str) -> &serde_json::Value {
        &self.entry(label)["meta"]
    }

    /// Labels in insertion order (serde_json's map is sorted, so order by offset).
    pub fn labels(&self) -> Vec<String> {
        let mut v: Vec<(u64, String)> = self
            .entries
            .iter()
            .map(|(k, e)| (e["offset"].as_u64().unwrap(), k.clone()))
            .collect();
        v.sort();
        v.into_iter().map(|(_, k)| k).collect()
    }
}

/// A meta number; non-finite values are stored as "nan", "inf", "-inf".
pub fn num(v: &serde_json::Value) -> f64 {
    match v.as_str() {
        Some("nan") => f64::NAN,
        Some("inf") => f64::INFINITY,
        Some("-inf") => f64::NEG_INFINITY,
        Some(s) => panic!("not a number: {s:?}"),
        None => v.as_f64().unwrap_or_else(|| panic!("not a number: {v}")),
    }
}

pub fn nums(v: &serde_json::Value) -> Vec<f64> {
    v.as_array().expect("array").iter().map(num).collect()
}

pub fn ints(v: &serde_json::Value) -> Vec<usize> {
    v.as_array()
        .expect("array")
        .iter()
        .map(|x| x.as_u64().unwrap() as usize)
        .collect()
}

/// Per-sample tolerance of the plan: |a-b| <= 1e-9 + 1e-9*|b|.
pub fn assert_close(got: &[f64], want: &[f64], what: &str) {
    assert_eq!(got.len(), want.len(), "{what}: length");
    for (i, (&a, &b)) in got.iter().zip(want).enumerate() {
        let ok = a == b || (a.is_nan() && b.is_nan()) || (a - b).abs() <= 1e-9 + 1e-9 * b.abs();
        assert!(ok, "{what}[{i}]: got {a}, want {b}");
    }
}

/// Registry defaults with `{name: value}` overrides from a reference meta.
pub fn params_from(overrides: &serde_json::Value) -> nomad_core::params::ParamValues {
    use nomad_core::params::{SYNTH_PARAMS, default_values};
    let mut p = default_values();
    for (name, v) in overrides.as_object().expect("params object") {
        let i = SYNTH_PARAMS
            .iter()
            .position(|s| s.name == name)
            .unwrap_or_else(|| panic!("{name}"));
        p[i] = num(v);
    }
    p
}

/// One audio callback of `Engine.render` for a single Internal instance at unity
/// level (no master gain or limiter): poll, chunk to the next event, render in
/// CONTROL_BLOCK slices, advance the sequencer and the clock, and a final poll.
/// Events (notes, commands) are applied by the caller between callbacks, which is
/// where Python's drain applies them.
pub fn run_single_instrument(
    synth: &mut nomad_core::synth::Synth,
    clock: &mut nomad_core::clock::Clock,
    clock_id: u64,
    out: &mut [f64],
) {
    use nomad_core::synth::CONTROL_BLOCK;
    let total = out.len();
    let mut i = 0;
    while i < total {
        synth.poll_sequencer(clock, clock_id);
        let chunk = (total - i).min(synth.frames_to_event(clock) as usize);
        for block in out[i..i + chunk].chunks_mut(CONTROL_BLOCK) {
            block.fill(0.0);
            synth.render_block(block);
        }
        synth.advance_sequencer(chunk as i64);
        clock.advance(chunk as i64);
        i += chunk;
    }
    synth.poll_sequencer(clock, clock_id);
}

/// `DrumMachine.render`: the standalone driver of a machine with its own clock.
pub fn drums_render(
    dm: &mut nomad_core::drums::DrumMachine,
    clock: &mut nomad_core::clock::Clock,
    clock_id: u64,
    out: &mut [f64],
) {
    let n = out.len();
    if n == 0 || dm.is_idle(clock) {
        return;
    }
    let mut i = 0;
    while i < n {
        dm.poll(clock, clock_id);
        let chunk = (n - i).min(dm.frames_to_event(clock) as usize);
        dm.render_chunk(&mut out[i..i + chunk]);
        clock.advance(chunk as i64);
        i += chunk;
    }
}

/// Sum and sum of squares, compared against the Python checksums.
pub fn assert_checksums(full: &[f64], meta: &serde_json::Value, what: &str) {
    let sum: f64 = full.iter().sum();
    let sumsq: f64 = full.iter().map(|x| x * x).sum();
    for (got, key) in [(sum, "sum"), (sumsq, "sumsq")] {
        let want = num(&meta[key]);
        assert!(
            (got - want).abs() <= 1e-6 + 1e-9 * want.abs(),
            "{what} {key}: {got} vs {want}"
        );
    }
}

/// Interpreter for mixer/topology operation lists shared by engine.rs and
/// topology.rs. Returns the full audio, per-render checksums, own-clock states
/// after each render and the boolean returns of commands that report one.
pub struct EngineRun {
    pub audio: Vec<f64>,
    pub sums: Vec<[f64; 2]>,
    pub clocks: Vec<Vec<[f64; 3]>>,
    pub returns: Vec<bool>,
}

pub fn run_engine_ops(
    e: &mut nomad_core::engine::Engine,
    commands: &serde_json::Value,
) -> EngineRun {
    use nomad_core::params::SYNTH_PARAMS;
    let mut r = EngineRun {
        audio: Vec::new(),
        sums: Vec::new(),
        clocks: Vec::new(),
        returns: Vec::new(),
    };
    for c in commands.as_array().unwrap() {
        let c = c.as_array().unwrap();
        let id = |k: usize| c[k].as_u64().unwrap() as u32;
        match c[0].as_str().unwrap() {
            "note_on" => e.note_on(c[1].as_i64().unwrap(), num(&c[2])),
            "note_off" => e.note_off(c[1].as_i64().unwrap()),
            "start" => r.returns.push(e.start(id(1))),
            "stop" => r.returns.push(e.stop(id(1))),
            "bpm" => r.returns.push(e.set_bpm(id(1), num(&c[2]))),
            "mute" => e.set_mute(id(1), c[2].as_bool().unwrap()),
            "level" => e.set_level(id(1), num(&c[2])),
            "master" => e.set_master_volume(num(&c[1])),
            "param" => {
                let name = c[1].as_str().unwrap();
                let p = SYNTH_PARAMS.iter().position(|s| s.name == name).unwrap();
                e.set_param(p, num(&c[2]));
            }
            "render" => {
                let mut o = vec![0.0; c[1].as_u64().unwrap() as usize];
                e.render(&mut o);
                r.sums.push([o.iter().sum(), o.iter().map(|x| x * x).sum()]);
                r.clocks.push(e.own_clock_states());
                r.audio.extend(o);
            }
            other => panic!("unknown op {other}"),
        }
    }
    r
}

/// Compare an `EngineRun` against a reference entry (decimated audio, checksums, clocks).
pub fn assert_engine_run(r: &EngineRun, blob: &Blob, label: &str) {
    let m = blob.meta(label);
    let decim = m["decim"].as_u64().unwrap() as usize;
    let got: Vec<f64> = r.audio.iter().copied().step_by(decim).collect();
    assert_close(&got, blob.get(label), label);
    let sums: Vec<Vec<f64>> = serde_json::from_value(m["sums"].clone()).unwrap();
    assert_eq!(sums.len(), r.sums.len(), "{label}");
    for (g, w) in r.sums.iter().zip(&sums) {
        for k in 0..2 {
            assert!(
                (g[k] - w[k]).abs() <= 1e-6 + 1e-9 * w[k].abs(),
                "{label} checksum {g:?} vs {w:?}"
            );
        }
    }
    let clocks: Vec<Vec<Vec<f64>>> = serde_json::from_value(m["clocks"].clone()).unwrap();
    assert_eq!(clocks.len(), r.clocks.len(), "{label}");
    for (g, w) in r.clocks.iter().zip(&clocks) {
        assert_eq!(g.len(), w.len(), "{label} instances");
        for (gc, wc) in g.iter().zip(w) {
            assert_close(gc, wc, &format!("{label} clock"));
        }
    }
    let rets: Vec<bool> = serde_json::from_value(m["returns"].clone()).unwrap();
    assert_eq!(r.returns, rets, "{label} returns");
}
